package com.skylanka.air.user.repository; import com.skylanka.air.user.entity.User; import com.skylanka.air.shared.entity.Role; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface UserRepository extends JpaRepository<User,Long>{Optional<User> findByEmail(String email); long countByRole(Role role); List<User> findByRole(Role role); List<User> findByRoleAndMarketingOptInTrueAndGuestFalse(Role role); long countByRoleAndActiveTrue(Role role);}
